#ifndef EMGPILL_H
#define EMGPILL_H

#include <Arduino.h>

#include "Eris.h"
#include <eriscommon.h>
#include <eris_sensor.h>   // ERIS_SENSOR

/*
 * EMGPill: EMG_NUMCHANNELS analog EMG front-ends on the built-in ADC, polled
 * at EMG_HZ by a single thread (generated by ERIS_SENSOR in emgpill.cpp). All
 * channels in a tick share one timestamp.
 */
namespace EMGPill{

extern ErisBuffer<EMGPillSample_t> buffer;
void start(void);   // generated by ERIS_SENSOR

void begin(void);   // ADC setup + banner, then start()

}

#endif
